      opts: { es: ['Operaciones fuera de un changeset atómico: fallo parcial sin rollback', 'El sistema es lento', 'Falta un índice'], en: ['Operations outside an atomic changeset: partial failure without rollback', 'Slow system', 'Missing index'], de: ['Kein Changeset: Teilausfall', 'Langsam', 'Index'] },
      correct: 0,
