      senior: [{ es: 'Inspecciona el diseño del lote', en: 'Inspect the batch design' }, { es: 'Agrupa pedido+líneas en un changeset', en: 'Group order+lines in a changeset' }, { es: 'Prueba el caso de fallo deliberado', en: 'Test the deliberate failure case' }],
      dwhy: { es: ['La lentitud retrasa; no produce huérfanos estructurales.', 'El índice afecta velocidad, no atomicidad.', 'La ausencia de change set es la causa más frecuente del medio-documento: sin él no hay rollback conjunto.'], en: ['Slowness delays; it does not produce structural orphans.', 'Indexes affect speed, not atomicity.', 'A missing change set is the most frequent half-document cause: without it there is no joint rollback.'], de: ['Langsamkeit verzögert nur.', 'Index ist nicht Atomarität.', 'Fehlendes Change Set ist die häufigste Ursache: ohne es kein gemeinsames Rollback.'] },
